'use strict';
const auditState={tab:'taiwan',query:'',gaps:false};
const auditTabs={taiwan:'Тайвань · маршруты',local:'Коста-Рика / Мексика',southamerica:'Южная Америка',europe:'Швейцария / Испания / Франция','europe-north':'Германия / Нидерланды / Бельгия','europe-south':'Италия / Португалия',southeastasia:'Юго-Восточная Азия','asia-english':'Сингапур / Гонконг',eastasia:'Япония / Китай / Тайвань',africa:'Африка · семейные маршруты',middleeast:'ОАЭ / Оман / Катар / Саудовская Аравия',continents:'Континенты',leagues:'Лиги и программы',exhibitions:'Крупные выставки',added:'Добавлено',remaining:'Что осталось'};
const auditGateLabels={family:'Со взрослым',adults_only:'Детям 6/9 нельзя',confirm_children:'Детский допуск уточнить'};
function renderCompletenessAudit(){
  const root=$('#completeness-audit'),a=DATA.completeness_audit,n=a.counts;
  if(!$('#audit-body'))root.innerHTML=`<div class="audit-heading"><div><p class="section-kicker">АУДИТ ПОЛНОТЫ · ${esc(a.checked)}</p><h3>Мир в базе.<br>Пробелы тоже видны.</h3></div><span class="audit-status">Исследование продолжается</span></div><p class="audit-verdict">${esc(a.conclusion)}</p><p class="audit-scope">${esc(a.scope)}</p><div class="audit-metrics">${[[n.league_profiles,'профилей лиг и программ',a.baseline.league_profiles],[n.competition_cards,'карточек соревнований',a.baseline.competition_cards],[n.major_exhibition_cards,'выставочных карточек',a.baseline.major_exhibition_cards],[n.countries_with_records,'стран и территорий с записями',a.baseline.countries_with_records]].map(([count,label,before])=>`<div><strong>${count}</strong><span>${esc(label)}</span><small>${before} → ${count} после аудита</small></div>`).join('')}</div><div class="audit-bias"><div><b>VEX · ${n.vex_cards} из ${n.competition_cards}</b><span>${(100*n.vex_cards/n.competition_cards).toFixed(1)}% карточек соревнований относятся к одной сети</span></div><div class="audit-bias-track" role="img" aria-label="Доля VEX среди карточек соревнований ${(100*n.vex_cards/n.competition_cards).toFixed(1)} процента"><span style="width:${100*n.vex_cards/n.competition_cards}%"></span></div><p>Это доля записей в базе. Полнота мирового календаря по этой диаграмме не определяется.</p></div><div class="audit-tabs" role="tablist" aria-label="Раздел аудита">${Object.entries(auditTabs).map(([id,label])=>`<button role="tab" id="audit-tab-${id}" data-audit-tab="${id}" aria-controls="audit-body">${esc(label)}${id==='added'?` <small>+${a.new_ids.length}</small>`:''}</button>`).join('')}</div><div class="audit-filters" id="audit-filters"><label>Поиск в этом разделе<input type="search" id="audit-search" placeholder="Название, страна или направление"></label><label class="audit-gap-filter" id="audit-gap-label"><input type="checkbox" id="audit-gaps"> Только записи с уточнениями</label></div><p class="audit-list-count" id="audit-list-count" role="status"></p><div id="audit-body" role="tabpanel"></div><div class="audit-downloads"><a class="button secondary" href="downloads/STEM_completeness_audit.md" download>Весь отчёт · Markdown</a><a class="button secondary" href="downloads/STEM_completeness_audit.json" download>Инвентарь и пробелы · JSON</a></div><details class="audit-boundaries"><summary>Что означает эта проверка</summary><ul>${a.caveats.map(t=>`<li>${esc(t)}</li>`).join('')}</ul><p>Все ${n.cards} карточек сохранены в выгрузках. Полностью завершённых местных аудитов: ${n.fully_audited_countries} из ${DATA.coverage_summary.countries} стран и территорий.</p><h4>Расхождения первичных источников</h4>${a.source_issues.map(s=>`<p><b>${esc(s.name)}.</b> ${esc(s.status)}${s.official_alternative?` <a href="${esc(s.official_alternative)}" target="_blank" rel="noopener">Официальная альтернатива ↗</a>`:''}</p>`).join('')}</details>`;
  $$('[data-audit-tab]').forEach(b=>{const on=b.dataset.auditTab===auditState.tab;b.classList.toggle('active',on);b.setAttribute('aria-selected',String(on));b.tabIndex=on?0:-1});
  $('#audit-filters').hidden=['continents','taiwan','local','southamerica','europe','europe-north','europe-south','southeastasia','asia-english','eastasia','africa','middleeast'].includes(auditState.tab);$('#audit-gap-label').hidden=!['leagues','exhibitions'].includes(auditState.tab);
  $('#audit-search').value=auditState.query;$('#audit-gaps').checked=auditState.gaps;
  $('#audit-body').setAttribute('aria-labelledby','audit-tab-'+auditState.tab);
  renderAuditBody();
}
function auditMatches(value){return JSON.stringify(value).toLocaleLowerCase('ru').includes(auditState.query.trim().toLocaleLowerCase('ru'))}
function auditSource(url){return url?`<a class="audit-source" href="${esc(url)}" target="_blank" rel="noopener">Официальный источник ↗</a>`:''}
function renderAuditBody(){
  const a=DATA.completeness_audit,box=$('#audit-body'),count=$('#audit-list-count');
  if(auditState.tab==='taiwan'){
    const t=a.focused_country,local=EVENTS.filter(e=>e.iso.includes(t.iso));
    count.textContent=`${local.length} карточек Тайваня · ${local.filter(e=>e.block==='Соревнования').length} соревнований / путей · ${local.filter(e=>e.block==='События').length} событий · ${local.filter(e=>e.block==='Лагеря').length} программ`;
    box.innerHTML=`<div class="taiwan-intro"><p class="section-kicker">ТАЙВАНЬ · ПЕРСОНАЛЬНЫЙ МАРШРУТ</p><h4>Два возраста.<br>Разные пути участия.</h4><p>${esc(t.family)}</p><p>${esc(t.conclusion)}</p><button class="button primary" data-taiwan-catalog="true">Все ${local.length} карточек Тайваня →</button></div><div class="taiwan-routes">${t.routes.map((r,i)=>`<article><span class="audit-index">${String(i+1).padStart(2,'0')}</span><h4>${esc(r.name)}</h4><p>${esc(r.detail)}</p><div class="taiwan-route-links">${r.ids.map(id=>{const e=EVENTS.find(e=>e.id===id);return `<button data-open="${esc(id)}">${esc(e.title)} <span>↗</span></button>`}).join('')}</div></article>`).join('')}</div><p class="audit-footnote">${esc(t.language_result)}</p><details class="audit-boundaries"><summary>Что ещё проверить перед поездкой</summary><ul>${t.open_questions.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><h4>Проверена реальная география</h4>${t.rejected_geographies.map(x=>`<p><b>${esc(x.name)} → ${esc(x.actual_country)}.</b> ${esc(x.reason)}</p>`).join('')}</details><div class="audit-downloads"><a class="button secondary" href="downloads/STEM_Taiwan.md" download>Тайвань · весь отчёт</a><a class="button secondary" href="downloads/STEM_Taiwan.json" download>Тайвань · данные с источниками</a></div>`;
  } else if(auditState.tab==='local'){
    const t=a.local_focus,local=EVENTS.filter(e=>e.iso.some(i=>['CRI','MEX'].includes(i)));
    const eventLinks=ids=>ids.map(id=>{const e=EVENTS.find(e=>e.id===id);return e?`<button data-open="${esc(id)}">${esc(e.title)} ↗</button>`:''}).join('');
    count.textContent=`${local.length} карточек Коста-Рики и Мексики · это инвентарь базы, не полный местный календарь`;
    box.innerHTML=`<div class="taiwan-intro local-intro"><p class="section-kicker">РЯДОМ С ДОМОМ · ПЕРСОНАЛЬНЫЕ МАРШРУТЫ</p><h4>Ближайший старт.<br>Каникулы и следующий уровень.</h4><p>${esc(t.family)}</p><p>${esc(t.conclusion)}</p><div class="taiwan-route-links"><button class="button primary" data-country-catalog="CRI">Все карточки Коста-Рики →</button><button class="button secondary" data-country-catalog="MEX">Все карточки Мексики →</button></div></div>${renderEuropeFamilyPicks(t,eventLinks)}<div class="taiwan-routes local-routes">${t.routes.map((r,i)=>`<article><span class="audit-index">${String(i+1).padStart(2,'0')}</span><h4>${esc(r.name)}</h4><p>${esc(r.detail)}</p><div class="taiwan-route-links">${r.ids.map(id=>{const e=EVENTS.find(e=>e.id===id);return `<button data-open="${esc(id)}">${esc(e.title)} <span>↗</span></button>`}).join('')}</div></article>`).join('')}</div><p class="audit-footnote">${esc(t.language_result)}</p><details class="audit-boundaries"><summary>Условия, которые ещё нужно подтвердить</summary><ul>${t.open_questions.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></details><div class="audit-downloads"><a class="button secondary" href="downloads/STEM_CostaRica_Mexico.md" download>Коста-Рика / Мексика · отчёт</a><a class="button secondary" href="downloads/STEM_CostaRica_Mexico.json" download>Коста-Рика / Мексика · данные</a></div>`;
  } else if(auditState.tab==='southamerica'){
    const t=a.south_america_focus,rows=EVENTS.filter(e=>e.iso.some(i=>t.isos.includes(i))),countries=COUNTRIES.filter(c=>t.isos.includes(c.iso));
    count.textContent=`${rows.length} карточек пяти проверенных направлений · это частичный проход, не полный календарь Южной Америки`;
    box.innerHTML=`<div class="taiwan-intro south-america-intro"><p class="section-kicker">ЮЖНАЯ АМЕРИКА · СЕМЕЙНЫЕ МАРШРУТЫ</p><h4>Каникулы на юге.<br>Свой путь к соревнованиям.</h4><p>${esc(t.family)}</p><p>${esc(t.conclusion)}</p><div class="taiwan-route-links">${countries.map(c=>`<button class="button secondary" data-country-catalog="${esc(c.iso)}">${esc(c.country)} →</button>`).join('')}</div></div><div class="taiwan-routes south-america-routes">${t.routes.map((r,i)=>`<article><span class="audit-index">${String(i+1).padStart(2,'0')}</span><h4>${esc(r.name)}</h4><p>${esc(r.detail)}</p><div class="taiwan-route-links">${r.ids.map(id=>{const e=EVENTS.find(e=>e.id===id);return `<button data-open="${esc(id)}">${esc(e.title)} <span>↗</span></button>`}).join('')}</div></article>`).join('')}</div><p class="audit-footnote">${esc(t.language_result)}</p><details class="audit-boundaries"><summary>Условия, которые ещё нужно подтвердить</summary><ul>${t.open_questions.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></details><div class="audit-downloads"><a class="button secondary" href="downloads/STEM_South_America.md" download>Южная Америка · отчёт</a><a class="button secondary" href="downloads/STEM_South_America.json" download>Южная Америка · данные</a></div>`;
  } else if(auditState.tab==='europe'){
    renderEuropeFocus(box,count);
  } else if(auditState.tab==='europe-north'){
    renderEuropeFocus(box,count,DATA.north_europe_focus,'STEM_Europe_DEU_NLD_BEL');
  } else if(auditState.tab==='europe-south'){
    renderEuropeFocus(box,count,DATA.south_europe_focus,'STEM_Europe_ITA_PRT');
  } else if(auditState.tab==='eastasia'){
    renderEuropeFocus(box,count,DATA.east_asia_focus,'STEM_East_Asia_JPN_CHN_TWN');
  } else if(auditState.tab==='asia-english'){
    renderEuropeFocus(box,count,DATA.asia_english_focus,'STEM_Singapore_HongKong');
  } else if(auditState.tab==='southeastasia'){
    renderEuropeFocus(box,count,DATA.southeast_asia_focus,'STEM_Southeast_Asia');
  } else if(auditState.tab==='middleeast'){
    renderEuropeFocus(box,count,DATA.middleeast_focus,'STEM_Middle_East');
  } else if(auditState.tab==='africa'){
    renderEuropeFocus(box,count,DATA.africa_focus,'STEM_Africa');
  } else if(auditState.tab==='continents'){
    count.textContent='Шесть обитаемых континентов представлены; каждый исследован частично.';
    const max=Math.max(...a.continents.map(c=>c.total));
    box.innerHTML=`<div class="audit-legend"><span class="comp">Соревнования</span><span class="expo">Все выставки / события</span><span class="camp">Лагеря / обучение</span></div><div class="audit-continents">${a.continents.map((c,i)=>`<article><div class="audit-continent-title"><span class="audit-index">0${i+1}</span><h4>${esc(c.name)}</h4><strong>${c.total}<small>карточек</small></strong></div><div class="audit-continent-bar" role="img" aria-label="${esc(c.name)}: ${c.competitions} соревнований, ${c.events} выставок и событий, ${c.camps} лагерей"><span class="comp" style="width:${100*c.competitions/max}%"></span><span class="expo" style="width:${100*c.events/max}%"></span><span class="camp" style="width:${100*c.camps/max}%"></span></div><div class="audit-continent-counts"><span><b>${c.competitions}</b>соревнований</span><span><b>${c.major_exhibitions}</b>крупных выставок</span><span><b>${c.camps}</b>лагерей / программ</span></div><p class="audit-continent-countries">${c.countries_with_records} стран / территорий с записями · ${esc(c.status)}</p><details><summary>Оставшиеся направления</summary><p>${esc(c.remaining)}</p></details></article>`).join('')}</div><p class="audit-footnote">Длина полос — число карточек, масштаб одинаковый для всех континентов. Глобальные и межрегиональные записи (${a.interregional_cards}) показаны отдельно от континентов. Северная Америка включает Центральную Америку и Карибский регион. Антарктида: релевантный местный календарь в рамках проверки не найден.</p>`;
  } else if(auditState.tab==='leagues'){
    const all=a.league_inventory,rows=all.filter(g=>auditMatches(g)&&(!auditState.gaps||!g.cards||!g.future_dated));
    count.textContent=`${rows.length} из ${all.length} профилей · ${all.filter(g=>!g.cards).length} без календарных карточек · ${all.filter(g=>g.cards&&!g.future_dated).length} с карточками, но без будущих точных дат`;
    box.innerHTML=`<p class="audit-footnote">Профиль может описывать семейство с несколькими дисциплинами. Наличие карточек подтверждает присутствие в базе, а не полный национальный календарь. Фильтр уточнений показывает отсутствие этапов или будущих дат.</p><div class="audit-inventory">${rows.map(g=>`<article><div><h4>${esc(g.name)}${g.new?'<small class="audit-new">Добавлено</small>':''}</h4><p>${esc(g.status)}</p><div class="audit-inventory-meta"><span>${g.cards} карточек</span><span class="${g.future_dated?'':'audit-unknown'}">${g.future_dated} с будущими датами</span></div></div><div class="audit-row-actions"><button class="league-link" data-audit-league="${esc(g.id)}">Возраст и путь отбора →</button>${auditSource(g.source)}</div></article>`).join('')}</div>`;
  } else if(auditState.tab==='exhibitions'){
    const all=a.exhibition_inventory,rows=all.filter(e=>auditMatches(e)&&(!auditState.gaps||!e.start||e.visitor_policy==='confirm_children')).sort((x,y)=>(x.start||'9999').localeCompare(y.start||'9999'));
    count.textContent=`${rows.length} из ${all.length} карточек · выпуски одной выставки считаются отдельно`;
    box.innerHTML=`<p class="audit-footnote">Это редакционный список крупных робототехнических, промышленных и AI / tech выставок. Общего официального списка «всех крупнейших» нет. Фильтр уточнений показывает неизвестную дату или детский допуск.</p><div class="audit-inventory">${rows.map(e=>`<article><div><h4>${esc(e.name)}${e.new?'<small class="audit-new">Добавлено</small>':''}</h4><p>${esc(e.country)} · ${e.start?shortDate(e.start)+(e.end!==e.start?' — '+shortDate(e.end):''):'Следующая дата неизвестна'}</p><span class="audit-gate ${esc(e.visitor_policy)}">${esc(auditGateLabels[e.visitor_policy])}</span></div><div class="audit-row-actions"><button class="league-link" data-open="${esc(e.id)}">Пропуск, возраст и программа →</button>${auditSource(e.source)}</div></article>`).join('')}</div>`;
  } else if(auditState.tab==='added'){
    const all=EVENTS.filter(e=>a.new_ids.includes(e.id)),rows=all.filter(auditMatches);
    count.textContent=`${rows.length} из ${all.length} новых карточек · ${a.new_profiles.length} новых профилей · источники и ограничения — в каждой карточке`;
    box.innerHTML=`<div class="audit-inventory">${rows.map(e=>`<article><div><p class="section-kicker">${esc(e.block)} · ${esc(e.id)}</p><h4>${esc(e.title)}</h4><p>${esc(e.country)} · ${e.start?shortDate(e.start)+(e.end!==e.start?' — '+shortDate(e.end):''):'Следующие даты не объявлены'}</p></div><div class="audit-row-actions"><button class="league-link" data-open="${esc(e.id)}">Открыть карточку →</button>${auditSource(e.source)}</div></article>`).join('')}</div>`;
  } else {
    const rows=a.known_backlog.filter(auditMatches);count.textContent=`${rows.length} из ${a.known_backlog.length} известных направлений · список пробелов тоже не исчерпывающий`;
    box.innerHTML=`<div class="audit-backlog">${rows.map((b,i)=>`<article><span class="audit-index">${String(i+1).padStart(2,'0')}</span><div><p class="section-kicker">${esc(b.kind)}</p><h4>${esc(b.name)}</h4><p>${esc(b.reason)}</p>${b.url?`<a class="audit-source" href="${esc(b.url)}" target="_blank" rel="noopener">Страница для следующей проверки ↗</a>`:''}</div></article>`).join('')}</div><p class="audit-footnote">Отсутствие записи означает пробел этого исследования. Оно не доказывает отсутствие соревнований или выставок в стране.</p>`;
  }
  if(auditState.query&&!box.querySelector('article'))box.innerHTML='<p class="audit-empty">Совпадений нет. Попробуйте другое название или снимите фильтр.</p>';
}
document.addEventListener('click',e=>{
  const b=e.target.closest('button');if(!b)return;
  if(b.dataset.auditTab){Object.assign(auditState,{tab:b.dataset.auditTab,query:'',gaps:false});renderCompletenessAudit()}
  if(b.dataset.taiwanCatalog){Object.assign(state,{league:'',block:'',query:'',kid:'',region:'',country:'TWN',theme:'',language:'',languageMode:'',campProjects:false,scope:'',participation:'',admission:'',evidence:'',visitorPolicy:'',dates:'',priority:false,excluded:true});setView('catalog')}
  if(b.dataset.countryCatalog){Object.assign(state,{league:'',block:'',query:'',kid:'',region:'',country:b.dataset.countryCatalog,theme:'',language:'',languageMode:'',campProjects:false,scope:'',participation:'',admission:'',evidence:'',visitorPolicy:'',dates:'',priority:false,excluded:true});setView('catalog')}
  if(b.dataset.auditLeague){Object.assign(leagueState,{tab:'guide',query:'',age:'',group:''});leagueState.opened.add(b.dataset.auditLeague);setView('leagues');const el=$('#league-'+b.dataset.auditLeague);el.scrollIntoView({behavior:'smooth',block:'start'});el.querySelector('summary').focus({preventScroll:true})}
});
document.addEventListener('input',e=>{if(e.target.id==='audit-search'){auditState.query=e.target.value;renderAuditBody()}});
document.addEventListener('change',e=>{if(e.target.id==='audit-gaps'){auditState.gaps=e.target.checked;renderAuditBody()}});
document.addEventListener('keydown',e=>{if(!e.target.dataset.auditTab||!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const ids=Object.keys(auditTabs),i=ids.indexOf(auditState.tab),next=e.key==='Home'?0:e.key==='End'?ids.length-1:(i+(e.key==='ArrowRight'?1:-1)+ids.length)%ids.length;auditState.tab=ids[next];auditState.query='';auditState.gaps=false;renderCompletenessAudit();$('#audit-tab-'+auditState.tab).focus()});
